#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_refComp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_refComp(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_softness;
uniform float amzp_reverse;
uniform float amzp_gradSrc;
uniform float amzp_invertG;
uniform float amzp_gradAngle;
uniform float2 amzp_center;
uniform float amzp_contrast;
uniform float amzp_noiseScale;
uniform float amzp_noiseMix;
uniform float amzp_seed;
uniform float amzp_edgeWidth;
layout(color) uniform half4 amzp_edgeCol;
uniform float amzp_edgeInt;
uniform float amzp_fillMode;
layout(color) uniform half4 amzp_fillCol;
uniform float amzp_detail;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_aSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_aSpeed * 0.5) : p; }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p) {
        float n = floor(clamp(amzp_detail, 1.0, 10.0) + 0.5);
        float s = 0.0, a = 0.5, ws = 0.0;
        for (int i = 0; i < 10; i++) {
            if (float(i) >= n) break;
            s += a * vn(p); ws += a;
            p = advRot(p, 0.5) * 2.02 + float2(3.1, 7.7);
            a *= 0.5;
        }
        return s / max(ws, 1e-5);
    }
    float luma(float4 c) { return dot(c.rgb, float3(0.2126, 0.7152, 0.0722)); }
    float2 mirrorUV(float2 uv) { return 1.0 - abs(1.0 - mod(uv, 2.0)); }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 lay = layerAt(uv);
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if ((amzp_autop>0.5)) C = fract(prog(amzp_completion));
        if ((amzp_reverse>0.5)) C = 1.0 - C;
        float2 ctr = float2(0.5) + float2(amzp_center.x, -amzp_center.y) * pxs() / W;
        float sc = max(amzp_advScale, 0.01);
        float2 q = advRot((uv - ctr) * W, radians(amzp_advAngle)) / sc;
        float2 puv = q / W + ctr;
        float g;
        if (int(amzp_gradSrc) == 0) {
            g = luma(layerAt(mirrorUV(puv)));
        } else if (int(amzp_gradSrc) == 1) {
            float2 s = l2s(mirrorUV(puv));
            g = luma(amzTexture(1, clamp(s, 0.0, 1.0)));
        } else if (int(amzp_gradSrc) == 2) {
            float2 d = advRot(float2(1.0, 0.0), radians(amzp_gradAngle));
            float ext = abs(d.x) * W.x + abs(d.y) * W.y;
            g = dot(q, d) / max(ext, 1.0) + 0.5;
        } else if (int(amzp_gradSrc) == 3) {
            g = length(q) / max(length(W) * 0.5, 1.0);
        } else if (int(amzp_gradSrc) == 4) {
            g = fract(atan(q.y, q.x) / 6.28318531 - amzp_gradAngle / 360.0 + 2.0);
        } else if (int(amzp_gradSrc) == 5) {
            float2 r = advRot(q, radians(amzp_gradAngle));
            g = (abs(r.x) / max(W.x, 1.0) + abs(r.y) / max(W.y, 1.0));
        } else {
            g = fbm(q / max(amzp_noiseScale * pxs(), 1.0));
            g = (g - 0.5) * 1.8 + 0.5;
        }
        if (amzp_noiseMix > 0.0 && int(amzp_gradSrc) != 6) {
            float n = fbm(q / max(amzp_noiseScale * pxs(), 1.0));
            g = mix(g, n, amzp_noiseMix * 0.6) + (n - 0.5) * amzp_noiseMix * 0.4;
        }
        g = clamp((g - 0.5) * amzp_contrast + 0.5, 0.0, 1.0);
        if ((amzp_invertG>0.5)) g = 1.0 - g;
        float s = max(amzp_softness, 0.0005);
        float ew = max(amzp_edgeWidth, 0.0);
        float B = s + ew;
        float thr = C * (1.0 + B) - B;
        float vis = smoothstep(thr + ew, thr + ew + s, g);
        if (C <= 0.0) vis = 1.0;
        if (C >= 1.0) vis = 0.0;
        float edge = 0.0;
        if (ew > 0.0 && C > 0.0 && C < 1.0) edge = smoothstep(thr - s * 0.5 - 0.002, thr + 0.002, g) * (1.0 - vis);
        float4 gone = int(amzp_fillMode) == 1 ? float4(amzp_fillCol.rgb, 1.0) : float4(0.0);
        float4 R = mix(gone, lay, vis);
        float3 ec = amzp_edgeCol.rgb * amzp_edgeInt * edge;
        float ea = clamp(edge * amzp_edgeInt, 0.0, 1.0) * lay.a;
        R = float4(R.rgb * (1.0 - ea) + ec * lay.a, R.a + ea * (1.0 - R.a));
        R.rgb = min(R.rgb, float3(R.a));
        amzOutput = R;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
